import numpy as np,pandas as pd
from scipy.stats import spearmanr
from sklearn.metrics import ndcg_score
from sklearn.ensemble import ExtraTreesRegressor,RandomForestRegressor,GradientBoostingRegressor,RandomForestRegressor
from catboost import CatBoostRegressor
tr=pd.read_csv('b3_te_zt_extrapolation_train.csv'); po=pd.read_csv('b3_te_zt_extrapolation_pool.csv'); tr=tr[tr.target<3]
f=[c for c in po if c not in ['candidate_id','T']]; Q=po[f].values
def met(y,p):
 return (spearmanr(y,p).statistic,ndcg_score(y[None],p[None],k=10),len(set(np.argsort(p)[-10:])&set(np.argsort(y)[-10:])),len(set(np.argsort(p)[-10:])&set(np.argsort(y)[-20:])))
def make(kind,seed=2):
 if kind=='ET':return ExtraTreesRegressor(n_estimators=700,min_samples_leaf=2,max_features=.8,n_jobs=-1,random_state=seed)
 if kind=='RF':return RandomForestRegressor(n_estimators=700,min_samples_leaf=2,max_features=.8,n_jobs=-1,random_state=seed)
 if kind=='Cat':return CatBoostRegressor(iterations=500,depth=5,learning_rate=.04,l2_leaf_reg=5,verbose=False,random_seed=seed)
 if kind=='GB':return GradientBoostingRegressor(n_estimators=100,max_depth=2,loss='huber',random_state=seed)
# validation surfaces 300,400
te=tr[tr.T if False else tr['T']==500]
print('validation separate-temp models p400 and linear extrap')
for kind in ['ET','RF','Cat','GB']:
 ps=[]
 for temp in [300,400]:
  d=tr[tr['T']==temp]; m=make(kind);m.fit(d[f],d.target);ps.append(m.predict(te[f]))
 for fac in [0,0.5,1,1.5,2]:
  p=ps[1]+fac*(ps[1]-ps[0]);print(kind,fac,np.round(met(te.target.values,p),3))
# full surfaces
allp={}
print('\n800 rankings by temp-surface extrapolation')
for kind in ['ET','RF','Cat','GB']:
 ps=[]
 for temp in [300,400,500]:
  d=tr[tr['T']==temp];m=make(kind);m.fit(d[f],d.target);ps.append(m.predict(Q))
 for fac in [0,1,2,3]:
  p=ps[2]+fac*(ps[2]-ps[1]); allp[f'{kind}{fac}']=p
  ix=np.argsort(p)[::-1][:15]
  print(kind,fac,' '.join(f'{po.candidate_id.iloc[i]}:{p[i]:.2f}' for i in ix))
# nearest by each temp and extrapolation
X=tr[f].values;y=tr.target.values
print('\nKNN temp surfaces')
for k in [3,5,10,20]:
 ps=[]
 for temp in [300,400,500]:
  z=tr['T'].values==temp; Xt=X[z];yt=y[z]
  out=[]
  for q in Q:
   d=np.sqrt(((Xt-q)**2).sum(1));ix=np.argsort(d)[:k];w=1/(d[ix]+.02)**2;out.append((w*yt[ix]).sum()/w.sum())
  ps.append(np.array(out))
 for fac in [1,2,3]:
  p=ps[2]+fac*(ps[2]-ps[1]);ix=np.argsort(p)[::-1][:12]
  print('k',k,'fac',fac,' '.join(f'{po.candidate_id.iloc[i]}:{p[i]:.2f}' for i in ix))
