import pandas as pd,numpy as np
from scipy.stats import spearmanr
from sklearn.metrics import ndcg_score
tr=pd.read_csv('b3_te_zt_extrapolation_train.csv');po=pd.read_csv('b3_te_zt_extrapolation_pool.csv');tr=tr[tr.target<3].reset_index(drop=True)
f=[c for c in po if c not in ['candidate_id','T']]
def pred_local(db,Q,tq,k,h,power,ridge,pertemp=False):
 X=db[f].values;y=db.target.values;t=(db['T'].values-400)/100;out=[]
 for q in Q:
  d=np.sqrt(((X-q)**2).sum(1))
  if pertemp:
   ix=np.concatenate([np.where(db['T'].values==tt)[0][np.argsort(d[db['T'].values==tt])[:k]] for tt in sorted(db['T'].unique())])
  else:ix=np.argsort(d)[:k]
  if h: w=np.exp(-(d[ix]/h)**power)
  else:w=1/(d[ix]+.02)**power
  # local linear in normalized t, ridge slope toward global ~0.001/K = .1 per t unit
  A=np.c_[np.ones(len(ix)),t[ix]]; M=A.T@(w[:,None]*A)+np.diag([1e-8,ridge]); b=A.T@(w*y[ix])+np.array([0,ridge*.1]);coef=np.linalg.solve(M,b)
  out.append(coef@[1,(tq-400)/100])
 return np.array(out)
def met(y,p):
 return spearmanr(y,p).statistic,ndcg_score(y[None],p[None],k=10),len(set(np.argsort(p)[-10:])&set(np.argsort(y)[-10:])),len(set(np.argsort(p)[-10:])&set(np.argsort(y)[-20:]))
train=tr[tr['T']<500];test=tr[tr['T']==500]
res=[]
for per in [False,True]:
 for k in ([10,20,30,50,80] if not per else [3,5,10,20]):
  for h in [0,.05,.1,.2,.4]:
   for power in ([1,2] if h else [1,2]):
    for ridge in [.01,.1,1,10]:
     p=pred_local(train,test[f].values,500,k,h,power,ridge,per)
     m=met(test.target.values,p);res.append((m[1],m[0],m[2],m[3],per,k,h,power,ridge))
print('best ndcg')
for x in sorted(res,reverse=True)[:20]:print(np.round(x,3))
print('best spearman')
for x in sorted(res,key=lambda x:x[1],reverse=True)[:10]:print(np.round(x,3))
print('\nPool rankings selected robust params')
params=[(False,20,.1,1,.1),(False,30,.2,2,.1),(False,50,.2,1,1),(True,5,.1,1,.1),(True,10,.2,2,1),(True,10,.4,2,1),(False,30,0,2,1)]
for z in params:
 p=pred_local(tr,po[f].values,800,z[1],z[2],z[3],z[4],z[0]);ix=np.argsort(p)[::-1][:15]
 print(z,' '.join(f'{po.candidate_id.iloc[i]}:{p[i]:.2f}' for i in ix))
