# Bootstrap local linear model across neighborhood definitions; summarize rank probabilities.
def local(db,Q,k,h,power,ridge):
 X=db[f].values;y=db.target.values;t=(db['T'].values-400)/100;out=[]
 for q in Q:
  d=np.linalg.norm(X-q,axis=1);ix=np.argsort(d)[:k];w=np.exp(-(d[ix]/h)**power) if h else 1/(d[ix]+.02)**power
  A=np.c_[np.ones(len(ix)),t[ix]]; M=A.T@(w[:,None]*A)+np.diag([1e-8,ridge]);b=A.T@(w*y[ix])+[0,ridge*.1]
  out.append(np.linalg.solve(M,b)@[1,4])
 return np.array(out)
preds=[]
for k in [10,15,20,30,40,50,70]:
 for h in [.1,.15,.2,.3,.4]:
  for power in [1,2]:
   for ridge in [.1,1,10]:preds.append(local(tr,po[f].values,k,h,power,ridge))
P=np.array(preds); R=np.array([(-p).argsort().argsort()+1 for p in P])
summary=pd.DataFrame({'id':po.candidate_id,'median_pred':np.median(P,0),'median_rank':np.median(R,0),'mean_rank':R.mean(0),'p_top5':(R<=5).mean(0),'p_top10':(R<=10).mean(0)})
print(summary.sort_values(['mean_rank']).head(25).to_string(index=False))
